package main

import (
	"fmt"
	"io/ioutil"
	"net/http"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

// ReportGenerator handles PDF report generation from user-supplied templates
type ReportGenerator struct {
	TemplateDir string
	OutputDir   string
}

func NewReportGenerator() *ReportGenerator {
	return &ReportGenerator{
		TemplateDir: "/app/templates",
		OutputDir:   "/app/output",
	}
}

func (rg *ReportGenerator) HandleGenerate(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	// Parse multipart form with template file
	err := r.ParseMultipartForm(10 << 20) // 10MB max
	if err != nil {
		http.Error(w, "Failed to parse form", 400)
		return
	}

	templateFile, handler, err := r.FormFile("template")
	if err != nil {
		http.Error(w, "Template file required", 400)
		return
	}
	defer templateFile.Close()

	// Validate file extension
	ext := strings.ToLower(filepath.Ext(handler.Filename))
	if ext != ".tex" && ext != ".ltx" {
		http.Error(w, "Only .tex and .ltx files accepted", 400)
		return
	}

	// Read template content
	content, err := ioutil.ReadAll(templateFile)
	if err != nil {
		http.Error(w, "Failed to read template", 500)
		return
	}

	// Basic sanitization - remove obvious shell escapes
	templateStr := string(content)
	templateStr = strings.ReplaceAll(templateStr, "\\immediate\\write18", "")
	templateStr = strings.ReplaceAll(templateStr, "\\ShellEscape", "")

	// Write sanitized template to temp file
	tmpFile := filepath.Join(rg.TemplateDir, "input.tex")
	err = ioutil.WriteFile(tmpFile, []byte(templateStr), 0644)
	if err != nil {
		http.Error(w, "Failed to write template", 500)
		return
	}

	// Get user-specified document class options
	docOpts := r.FormValue("options")
	if docOpts == "" {
		docOpts = "12pt,a4paper"
	}

	// Compile LaTeX to PDF using pdflatex
	// Using -shell-escape for packages that need it (minted, svg, etc.)
	cmd := exec.Command("pdflatex",
		"-shell-escape",
		"-interaction=nonstopmode",
		"-output-directory="+rg.OutputDir,
		tmpFile,
	)
	cmd.Dir = rg.TemplateDir
	cmd.Env = append(os.Environ(), "TEXMFVAR=/tmp/texmf-var")

	output, err := cmd.CombinedOutput()
	if err != nil {
		w.Header().Set("Content-Type", "text/plain")
		w.WriteHeader(500)
		fmt.Fprintf(w, "Compilation failed:\n%s", string(output))
		return
	}

	// Serve the generated PDF
	pdfPath := filepath.Join(rg.OutputDir, "input.pdf")
	pdfContent, err := ioutil.ReadFile(pdfPath)
	if err != nil {
		http.Error(w, "Failed to read output PDF", 500)
		return
	}

	w.Header().Set("Content-Type", "application/pdf")
	w.Header().Set("Content-Disposition", "attachment; filename=report.pdf")
	w.Write(pdfContent)
}

func (rg *ReportGenerator) HandleHealth(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(200)
	w.Write([]byte(`{"status":"healthy","version":"2.1.4"}`))
}

func main() {
	rg := NewReportGenerator()

	http.HandleFunc("/generate", rg.HandleGenerate)
	http.HandleFunc("/health", rg.HandleHealth)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	fmt.Printf("Report generator listening on :%s\n", port)
	http.ListenAndServe(":"+port, nil)
}
